import java.util.*;

class Solution {
    public boolean subsetSumExists(int[] nums, int target) {
        return search(nums, 0, 0, target);
    }

    private boolean search(int[] nums, int index, int currentSum, int target) {
        if (currentSum == target) {
            return true;
        }
        if (index == nums.length || currentSum > target) {
            return false;
        }
        return search(nums, index + 1, currentSum + nums[index], target);
    }
}
